    {
      "keystrokes": "for f in /app/status6b/frame_0001.png /app/status6b/frame_0183.png /app/status6b/frame_0366.png /app/status6b/frame_0732.png /app/status6b/frame_1098.png; do echo \"=== $f ===\"; tesseract \"$f\" stdout --psm 7 2>/dev/null; done\n",
